// Technique: Loop Unrolling (Increasing Instruction-Level Parallelism - ILP)

int sum = 0;
int s0=0, s1=0, s2=0, s3=0;

// Original (High CPE due to loop overhead and dependencies)
// for (int i = 0; i < N; i++) { sum += A[i]; }

// Optimized: 4-way Unrolling
for (int i = 0; i < N; i += 4) {
    s0 += A[i];
    s1 += A[i+1];
    s2 += A[i+2];
    s3 += A[i+3];
}
sum = s0 + s1 + s2 + s3; // Final reduction step
// CPE reduced by factor of ~4 (ignoring cleanup)

// Technique: SIMD Vectorization (Maximizing Throughput per Cycle)
// Using SSE/AVX intrinsics to process multiple elements simultaneously

#include <immintrin.h>

// Vector Addition (Float, 4 elements per instruction)
void vec_add(float* A, float* B, float* C, int N) {
    for (int i = 0; i < N; i += 4) {
        __m128 vA = _mm_loadu_ps(&A[i]);
        __m128 vB = _mm_loadu_ps(&B[i]);
        __m128 vC = _mm_add_ps(vA, vB);
        _mm_storeu_ps(&C[i], vC);
    }
}
// Theoretical CPE for add instruction approaches 1/4 or 1/8
// (depending on vector width used, e.g., SSE vs AVX)
